331		}
332	
333		return &emptypb.Empty{}, nil
334	}
335	
336	func (s *APIV1Service) validateFilter(ctx context.Context, filterStr string) error {
337		if filterStr == "" {
338			return errors.New("filter cannot be empty")
339		}
340	
341		engine, err := filter.DefaultEngine()
342		if err != nil {
343			return err
344		}
345	
346		var dialect filter.DialectName
347		switch s.Profile.Driver {
348		case "mysql":
349			dialect = filter.DialectMySQL
350		case "postgres":
351			dialect = filter.DialectPostgres
352		default:
353			dialect = filter.DialectSQLite
354		}
355	
356		if _, err := engine.CompileToStatement(ctx, filterStr, filter.RenderOptions{Dialect: dialect}); err != nil {
357			return errors.Wrap(err, "failed to compile filter")
358		}
359		return nil
360	}
